// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: deep-gray; icon-glyph: chart-bar;

// NOTE: the three lines above are Scriptable's own metadata block and must stay
// first. Without them Scriptable inserts its own on import - and in doing so it
// consumes the leading "//" of whatever was on line 1, orphaning that text as
// bare code. The symptom is a syntax error on line 1 about an unexpected
// identifier. Keep this header; do not start the file with any other comment.

// Scriptable widget: Claude Code counter, drawn NATIVELY.
//
// Install:
//   1. Scriptable (free, App Store), open it once so iCloud creates its folder.
//   2. Copy this file into iCloud Drive > Scriptable/ (or paste into a new script
//      named "ClaudeCounter").
//   3. Home screen > add a Scriptable widget, size Large, choose ClaudeCounter.
//
// WHY THIS DRAWS TEXT INSTEAD OF SHOWING A PNG
//
// An earlier version used a pre-rendered image as the widget background. That is a
// photograph of text: the image has fixed pixel dimensions and iOS rescales it to
// the widget's real point size, which differs by device and widget family.
// Resampling by even a few percent puts every glyph edge between device pixels, so
// it reads soft beside native labels the OS draws at exact device resolution with
// hinting. No font change fixes a resampled bitmap.
//
// This reproduces that card's LAYOUT natively - the bordered chip, the hero panel,
// the 2x2 grid of tiles - using stack backgroundColor / cornerRadius / borderWidth.
//
// FONT: system (SF Pro), deliberately NOT the rounded variant. SF Rounded reads
// soft and generic at these sizes and does not match the rest of the home screen.
//
// MONOCHROME BY DEFAULT: set ACCENT = true if you ever want the orange back.

const ACCENT = false;

const BG      = new Color("#0a0a0d");
const INK     = new Color("#f4f2ef");
const MUTED   = new Color("#9a98a4");
const DIM     = new Color("#77757f");
const HOT     = ACCENT ? new Color("#ff9557") : new Color("#f4f2ef");
const TILE_FILL = new Color("#ffffff", 0.058);   // translucent on purpose:
                                                // the card ramp shows through
const TILE_BD  = new Color("#ffffff", 0.155);
const HERO_FILL = ACCENT ? new Color("#ff9557", 0.115) : new Color("#ffffff", 0.088);
const HERO_BD  = ACCENT ? new Color("#ff9557", 0.34) : new Color("#ffffff", 0.20);

// Tile inner padding, reused by the footer so it sits on the same text rail as
// everything else. Without this the footer hangs a full tile-padding to the left
// of every other line on the card.
const PAD = 13;

const DOT = "\u00b7";  // escaped on purpose: a literal middle dot has arrived
                        // double-encoded before, printing as a stray capital A

// TEXTURE_B64_START
const TEX_B64 =
  "";
// TEXTURE_B64_END

/**
 * The card background, embedded and applied to the WIDGET, not to a stack.
 *
 * That distinction is the whole thing. Setting backgroundImage on a nested stack
 * does not render inside a widget extension - it paints a blank white block over
 * the text, while looking perfectly fine in the in-app preview. Setting it on the
 * ListWidget works, which is how a full-card image rendered here originally.
 *
 * So the image carries NO features - just a dithered ramp, brighter at the
 * top-left. There is nothing to line up with, so it cannot drift out of register
 * on a different widget size. The tiles are semi-transparent flat fills drawn on
 * top, and being semi-transparent they let this ramp through: that is where their
 * texture and their lighting come from, without a per-tile image (impossible) or
 * a per-tile gradient (bands, because SwiftUI does not dither).
 */
function cardBackground() {
  if (!TEX_B64) return null;
  try {
    const img = Image.fromData(Data.fromBase64String(TEX_B64));
    return (img && img.size && img.size.width > 8) ? img : null;
  } catch (e) {
    return null;
  }
}

const FOLDER = "ClaudeCounter";

// Where the Mac drops stats.json, most reliable first. The flat file in
// Scriptable's Documents root is the primary: a subfolder has to propagate as a
// directory before its contents are visible, and on iOS that can lag or fail
// silently, which shows up here as "no data" while the Mac side is perfectly fine.
const CANDIDATES = [
  ["iCloud root",   () => FileManager.iCloud(), (fm) => "ClaudeCounter-stats.json"],
  ["iCloud folder", () => FileManager.iCloud(), (fm) => FOLDER + "/stats.json"],
  ["local root",    () => FileManager.local(),  (fm) => "ClaudeCounter-stats.json"],
  ["local folder",  () => FileManager.local(),  (fm) => FOLDER + "/stats.json"],
];

// The on-device copy of the last stats we successfully read, in Scriptable's
// LOCAL container - not iCloud. See readCache() for why this exists.
const CACHE = "ClaudeCounter-cache.json";

/**
 * Persist the last good payload locally.
 *
 * The whole point: iCloud is a *view* of a file, not a guarantee that its bytes
 * are on this phone. When the Mac is asleep the file is still listed, still
 * passes fileExists(), and still reports as downloaded - but the read comes back
 * empty, because the widget extension gets a couple of seconds of runtime and no
 * reliable way to materialise a dataless placeholder in that window. Writing our
 * own copy into the local container removes iCloud from the render path
 * entirely: once a value has been seen, it is ours.
 */
function writeCache(stats) {
  try {
    const fm = FileManager.local();
    fm.writeString(
      fm.joinPath(fm.documentsDirectory(), CACHE),
      JSON.stringify({ cached_at: new Date().toISOString(), stats }));
  } catch (e) { /* a cache miss must never break the render */ }
}

function readCache() {
  try {
    const fm = FileManager.local();
    const p = fm.joinPath(fm.documentsDirectory(), CACHE);
    if (!fm.fileExists(p)) return null;
    const raw = fm.readString(p);
    if (!raw) return null;
    const c = JSON.parse(raw);
    return c && c.stats ? c : null;
  } catch (e) { return null; }
}

/**
 * Try every known location and report what happened.
 * Deliberately does NOT bail on fileExists(): for an iCloud file that has not
 * been materialised on the device yet, the honest move is to attempt the
 * download and let the read decide, rather than trusting a stat that can be
 * false for a file that is really there.
 */
async function loadStats() {
  const tried = [];
  for (const [label, mk, rel] of CANDIDATES) {
    let fm;
    try { fm = mk(); } catch (e) { tried.push(`${label}: unavailable`); continue; }
    const path = fm.joinPath(fm.documentsDirectory(), rel(fm));
    try {
      if (fm.fileExists(path)) {
        if (fm.isFileStoredIniCloud(path) && !fm.isFileDownloaded(path)) {
          await fm.downloadFileFromiCloud(path);
        }
        let raw = fm.readString(path);
        // An empty read on a file that exists is the placeholder case, and
        // isFileDownloaded() lies about it often enough not to be trusted as the
        // only gate. Ask for the download unconditionally and read once more.
        if (!raw && fm.isFileStoredIniCloud(path)) {
          try {
            await fm.downloadFileFromiCloud(path);
            raw = fm.readString(path);
          } catch (e) { /* fall through to the cache */ }
        }
        if (raw) {
          const stats = JSON.parse(raw);
          writeCache(stats);
          return { stats, from: label };
        }
        tried.push(`${label}: empty`);
      } else {
        tried.push(`${label}: not found`);
      }
    } catch (e) {
      tried.push(`${label}: ${String(e).slice(0, 40)}`);
    }
  }

  // Nothing readable right now. Show the last numbers we ever saw rather than a
  // diagnostic screen: they are real, they are labelled with their own date, and
  // a slightly old card is worth more on a home screen than an error is.
  const cached = readCache();
  if (cached) return { stats: cached.stats, from: "cache", cached_at: cached.cached_at };

  // one listing of the root so the failure is diagnosable from the widget itself
  let seen = "";
  try {
    const fm = FileManager.iCloud();
    seen = fm.listContents(fm.documentsDirectory()).slice(0, 6).join(", ");
  } catch (e) { seen = "could not list"; }
  return { stats: null, tried, seen };
}

const money = (v) => "$" + Math.round(v).toLocaleString("en-US");
const num = (v) => v.toLocaleString("en-US");

/** A line of text inside a tile, with a trailing spacer so the tile grows to fill. */
function line(into, text, font, color, scale) {
  const r = into.addStack();
  r.layoutHorizontally();
  const t = r.addText(text);
  t.font = font;
  t.textColor = color;
  t.lineLimit = 1;
  t.minimumScaleFactor = scale || 0.7;
  r.addSpacer();          // greedy: two sibling tiles then split the row evenly
  return t;
}

/**
 * A tile. Uses a GRADIENT rather than a flat colour: a single uniform fill reads
 * dead next to the rest of the home screen, and the original card's tiles were
 * lit from the top-left. Subtle on purpose - the whole range is 0.03 alpha wide.
 */
/**
 * A tile.
 *
 * FLAT FILL, on purpose, after trying both alternatives on a real device:
 *
 *  - backgroundImage on a nested stack renders as a blank WHITE block inside a
 *    widget extension, hiding the text on top of it. It works in the in-app
 *    preview, which makes it look correct right up until it ships. True for both
 *    an iCloud file and an embedded base64 image, so it is the API, not the source.
 *  - backgroundGradient does render in a widget, but SwiftUI does not dither, so
 *    a ramp subtle enough to read as glass bands into visible stripes.
 *
 * That leaves a flat fill, which cannot band and cannot go white. The lit-edge
 * read comes from the border instead - which is what was carrying it anyway.
 */
function panel(into, fill, border, radius) {
  const s = into.addStack();
  s.layoutVertically();
  s.backgroundColor = fill;
  s.borderColor = border;
  s.borderWidth = 1;
  s.cornerRadius = radius;
  s.setPadding(13, 13, 13, 13);
  return s;
}

/** One stat tile: big numeral over a small label.
 *  `label` may be a string, or [plain, emphasised] to brighten the payoff word. */
function tile(into, value, label) {
  const s = panel(into, TILE_FILL, TILE_BD, 17);
  line(s, value, Font.boldSystemFont(22), INK, 0.5);
  s.addSpacer(2);
  if (Array.isArray(label)) {
    const r = s.addStack();
    r.layoutHorizontally();
    const a = r.addText(label[0] + " ");
    a.font = Font.systemFont(10); a.textColor = MUTED; a.lineLimit = 1;
    const b = r.addText(label[1]);
    b.font = Font.semiboldSystemFont(10); b.textColor = HOT; b.lineLimit = 1;
    r.addSpacer();
  } else {
    line(s, label, Font.systemFont(10), MUTED, 0.7);
  }
}

function build(s, diag) {
  const w = new ListWidget();
  w.backgroundColor = BG;               // stays as the fallback if decoding fails
  const bg = cardBackground();
  if (bg) w.backgroundImage = bg;
  w.setPadding(14, 14, 14, 14);

  if (!s) {
    const t = w.addText("Waiting for stats.json");
    t.font = Font.semiboldSystemFont(14);
    t.textColor = INK;
    const d = w.addText(
      (diag && diag.tried ? diag.tried.join("\n") : "") +
      (diag && diag.seen ? "\n\nDocuments: " + diag.seen : ""));
    d.font = Font.systemFont(9);
    d.textColor = MUTED;
    return w;
  }

  // ---- header: bordered chip, then the scope on the right -------------------
  const head = w.addStack();
  head.layoutHorizontally();
  head.centerAlignContent();

  const chip = head.addStack();
  chip.backgroundColor = ACCENT ? new Color("#ff9557", 0.10) : new Color("#ffffff", 0.07);
  chip.borderColor = ACCENT ? new Color("#ff9557", 0.22) : new Color("#ffffff", 0.16);
  chip.borderWidth = 1;
  chip.cornerRadius = 8;
  chip.setPadding(4, 8, 4, 8);
  const chipT = chip.addText(s.window.label);
  chipT.font = Font.semiboldSystemFont(10);
  chipT.textColor = HOT;

  head.addSpacer(8);
  const scope = head.addText("Claude Code");
  scope.font = Font.systemFont(11);
  scope.textColor = MUTED;
  head.addSpacer();

  w.addSpacer(10);

  // ---- hero panel: the cost is the headline ---------------------------------
  const hero = panel(w, HERO_FILL, HERO_BD, 18);
  line(hero, money(s.cost.api_equivalent_usd), Font.boldSystemFont(40), INK, 0.4);
  hero.addSpacer(3);
  line(hero, "at API list rates", Font.systemFont(10), MUTED, 0.7);

  if (s.cost.multiple != null) {
    hero.addSpacer(5);
    const r = hero.addStack();
    r.layoutHorizontally();
    r.bottomAlignContent();
    const x = r.addText(s.cost.multiple + "x");
    x.font = Font.boldSystemFont(15);
    x.textColor = HOT;
    r.addSpacer(7);
    const plan = r.addText(
      `my ${s.cost.plan_label} plan ${DOT} $${s.cost.plan_monthly_usd}/mo`);
    plan.font = Font.systemFont(11);  // 15 vs 11 keeps the baseline drift under a point
    plan.textColor = MUTED;
    plan.lineLimit = 1;
    plan.minimumScaleFactor = 0.7;
    r.addSpacer();
  }

  w.addSpacer(10);

  // ---- 2x2 grid of stat tiles ----------------------------------------------
  const rows = [
    [[num(s.me.messages), "messages I sent"],
     [num(s.claude.tool_calls), ["tools run", "for me"]]],
    [["1 in " + Math.round(s.phrases.corrections.one_in), ["are", "corrections"]],
     [num(s.claude.commits), "commits by Claude"]],
  ];
  rows.forEach((pair, i) => {
    if (i) w.addSpacer(10);
    const r = w.addStack();
    r.layoutHorizontally();
    tile(r, pair[0][0], pair[0][1]);
    r.addSpacer(10);
    tile(r, pair[1][0], pair[1][1]);
  });

  w.addSpacer(11);

  // ---- footer ---------------------------------------------------------------
  const df = new DateFormatter();
  df.dateFormat = "MMM d, h:mm a";
  const footRow = w.addStack();
  footRow.layoutHorizontally();
  footRow.setPadding(0, PAD, 0, 0);   // sit on the tile TEXT rail, not the tile edge
  // When we are rendering the local cache, say so. The timestamp is the Mac's
  // last generation either way, so without this marker a stale card is
  // indistinguishable from a live one that simply has not ticked over yet.
  const stale = diag && diag.from === "cache" ? ` ${DOT} cached` : "";
  const foot = footRow.addText(
    `${s.activity.active_days} active days ${DOT} updated ${df.string(new Date(s.generated_at))}${stale}`);
  foot.font = Font.systemFont(10);
  foot.textColor = DIM;
  foot.lineLimit = 1;
  foot.minimumScaleFactor = 0.7;
  footRow.addSpacer();

  return w;
}

const result = await loadStats();
const widget = build(result.stats, result);

if (config.runsInWidget) {
  Script.setWidget(widget);
} else {
  await widget.presentLarge();
}
Script.complete();
